use std::cmp::Ordering;

type TpplFloat = f64;

#[derive(Debug, Clone, Copy)]
pub struct TpplPoint {
    pub x: TpplFloat,
    pub y: TpplFloat,
}

impl TpplPoint {
    pub fn new(x: TpplFloat, y: TpplFloat) -> Self {
        TpplPoint { x, y }
    }

    pub fn distance(&self, other: &TpplPoint) -> TpplFloat {
        ((self.x - other.x).powi(2) + (self.y - other.y).powi(2)).sqrt()
    }

    pub fn normalize(self) -> Option<TpplPoint> {
        let n = (self.x.powi(2) + self.y.powi(2)).sqrt();
        if n != 0.0 {
            Some(TpplPoint::new(self.x / n, self.y / n))
        } else {
            None
        }
    }
}

impl PartialEq for TpplPoint {
    fn eq(&self, other: &Self) -> bool {
        self.x == other.x && self.y == other.y
    }
}

impl std::ops::Sub for TpplPoint {
    type Output = TpplPoint;

    fn sub(self, other: TpplPoint) -> TpplPoint {
        TpplPoint::new(self.x - other.x, self.y - other.y)
    }
}

#[derive(Debug, PartialEq, Clone, Copy)]
pub enum TpplOrientation {
    None,
    Cw,
    Ccw,
}

#[derive(Debug, Clone, Copy)]
struct ScanLineEdge {
    pub p1: TpplPoint,
    pub p2: TpplPoint,
    pub index: usize,
}

impl ScanLineEdge {
    fn is_convex(&self, p1: &TpplPoint, p2: &TpplPoint, p3: &TpplPoint) -> bool {
        let tmp = (p3.y - p1.y) * (p2.x - p1.x) - (p3.x - p1.x) * (p2.y - p1.y);
        tmp > 0.0
    }
}

impl PartialEq for ScanLineEdge {
    fn eq(&self, other: &Self) -> bool {
        self.index == other.index
    }
}

impl Eq for ScanLineEdge {}

impl PartialOrd for ScanLineEdge {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for ScanLineEdge {
    fn cmp(&self, other: &Self) -> Ordering {
        if other.p1.y == other.p2.y {
            if self.p1.y == self.p2.y {
                return self.p1.y.partial_cmp(&other.p1.y).unwrap();
            }
            return if self.is_convex(&self.p1, &self.p2, &other.p1) {
                Ordering::Greater
            } else {
                Ordering::Less
            };
        } else if self.p1.y == self.p2.y {
            return if !other.is_convex(&other.p1, &other.p2, &self.p1) {
                Ordering::Greater
            } else {
                Ordering::Less
            };
        } else if self.p1.y < other.p1.y {
            return if !other.is_convex(&other.p1, &other.p2, &self.p1) {
                Ordering::Greater
            } else {
                Ordering::Less
            };
        } else {
            return if self.is_convex(&self.p1, &self.p2, &other.p1) {
                Ordering::Greater
            } else {
                Ordering::Less
            };
        }
    }
}

#[derive(Clone)]
pub struct TpplPoly {
    hole: bool,
    points: Vec<TpplPoint>,
}

impl TpplPoly {
    pub fn new() -> Self {
        TpplPoly {
            hole: false,
            points: Vec::new(),
        }
    }

    pub fn init(&mut self, numpoints: usize) {
        self.points = vec![TpplPoint::new(0.0, 0.0); numpoints];
        self.hole = false;
    }

    pub fn triangle(&mut self, p1: TpplPoint, p2: TpplPoint, p3: TpplPoint) {
        self.init(3);
        self.points[0] = p1;
        self.points[1] = p2;
        self.points[2] = p3;
    }

    pub fn get_orientation(&self) -> TpplOrientation {
        let mut area = 0.0;
        for i in 0..self.points.len() {
            let j = if i + 1 < self.points.len() {
                i + 1
            } else {
                0
            };
            area += self.points[i].x * self.points[j].y - self.points[i].y * self.points[j].x;
        }
        if area > 0.0 {
            TpplOrientation::Ccw
        } else if area < 0.0 {
            TpplOrientation::Cw
        } else {
            TpplOrientation::None
        }
    }

    pub fn set_orientation(&mut self, orientation: TpplOrientation) {
        let polyorientation = self.get_orientation();
        if polyorientation != TpplOrientation::None && polyorientation != orientation {
            self.invert();
        }
    }

    pub fn invert(&mut self) {
        self.points.reverse();
    }

    pub fn get_num_points(&self) -> usize {
        self.points.len()
    }

    pub fn get_point(&self, i: usize) -> TpplPoint {
        self.points[i]
    }
}

pub struct TpplPartition;

impl TpplPartition {
    pub fn normalize(p: TpplPoint) -> TpplPoint {
        p.normalize().unwrap_or(TpplPoint::new(0.0, 0.0))
    }

    pub fn intersects(p11: TpplPoint, p12: TpplPoint, p21: TpplPoint, p22: TpplPoint) -> bool {
        if (p11 == p21) || (p11 == p22) || (p12 == p21) || (p12 == p22) {
            return false;
        }

        let v1ort = TpplPoint::new(p12.y - p11.y, p11.x - p12.x);
        let v2ort = TpplPoint::new(p22.y - p21.y, p21.x - p22.x);

        let v = p21 - p11;
        let dot21 = v.x * v1ort.x + v.y * v1ort.y;
        let v = p22 - p11;
        let dot22 = v.x * v1ort.x + v.y * v1ort.y;

        let v = p11 - p21;
        let dot11 = v.x * v2ort.x + v.y * v2ort.y;
        let v = p12 - p21;
        let dot12 = v.x * v2ort.x + v.y * v2ort.y;

        dot11 * dot12 <= 0.0 && dot21 * dot22 <= 0.0
    }

    pub fn remove_holes(inpolys: &mut Vec<TpplPoly>, outpolys: &mut Vec<TpplPoly>) -> bool {
        let hasholes = inpolys.iter().any(|poly| poly.hole);

        if !hasholes {
            outpolys.extend(inpolys.iter().cloned());
            return true;
        }

        let mut polys = inpolys.clone();

        loop {
            let holeiter_idx = polys.iter().position(|p| p.hole);
            if holeiter_idx.is_none() {
                break;
            }

            let holeiter = polys.remove(holeiter_idx.unwrap());
            let holepointindex = holeiter
                .points
                .iter()
                .enumerate()
                .max_by(|(_, a), (_, b)| a.x.partial_cmp(&b.x).unwrap())
                .map(|(i, _)| i)
                .unwrap();

            let holepoint = holeiter.points[holepointindex];

            let mut pointfound = false;
            let mut bestpolypoint = TpplPoint::new(0.0, 0.0);
            let mut polyiter_index = 0;
            let mut polypointindex = 0;

            for (pli, poly) in polys.iter().enumerate() {
                if poly.hole {
                    continue;
                }
                for (i, polypoint) in poly.points.iter().enumerate() {
                    if polypoint.x <= holepoint.x {
                        continue;
                    }

                    if !TpplPartition::in_cone(
                        &poly.get_point((i + poly.get_num_points() - 1) % poly.get_num_points()),
                        &polypoint,
                        &poly.get_point((i + 1) % poly.get_num_points()),
                        &holepoint,
                    ) {
                        continue;
                    }

                    let dist = holepoint.distance(&polypoint);
                    if !pointfound || dist < holepoint.distance(&bestpolypoint) {
                        let mut pointvisible = true;
                        for iter2 in polys.iter() {
                            if iter2.hole {
                                continue;
                            }
                            for i2 in 0..iter2.get_num_points() {
                                let linep1 = iter2.get_point(i2);
                                let linep2 = iter2.get_point((i2 + 1) % iter2.get_num_points());
                                if TpplPartition::intersects(holepoint, *polypoint, linep1, linep2)
                                {
                                    pointvisible = false;
                                    break;
                                }
                            }
                            if !pointvisible {
                                break;
                            }
                        }
                        if pointvisible {
                            pointfound = true;
                            bestpolypoint = *polypoint;
                            polyiter_index = pli;
                            polypointindex = i;
                        }
                    }
                }
            }

            if !pointfound {
                return false;
            }

            let mut newpoly = TpplPoly::new();
            newpoly.init(
                holeiter.get_num_points() + polys[polyiter_index].get_num_points() + 2,
            );

            let mut i2 = 0;
            for i in 0..=polypointindex {
                newpoly.points[i2] = polys[polyiter_index].get_point(i);
                i2 += 1;
            }
            for i in 0..=holeiter.get_num_points() {
                newpoly.points[i2] = holeiter.get_point((i + holepointindex) % holeiter.get_num_points());
                i2 += 1;
            }
            for i in polypointindex..polys[polyiter_index].get_num_points() {
                newpoly.points[i2] = polys[polyiter_index].get_point(i);
                i2 += 1;
            }

            polys[polyiter_index] = newpoly;
        }

        outpolys.extend(polys);
        true
    }

    pub fn is_convex(p1: &TpplPoint, p2: &TpplPoint, p3: &TpplPoint) -> bool {
        let tmp = (p3.y - p1.y) * (p2.x - p1.x) - (p3.x - p1.x) * (p2.y - p1.y);
        tmp > 0.0
    }

    pub fn in_cone(p1: &TpplPoint, p2: &TpplPoint, p3: &TpplPoint, p: &TpplPoint) -> bool {
        let convex = TpplPartition::is_convex(p1, p2, p3);
        if convex {
            TpplPartition::is_convex(p1, p2, p) && TpplPartition::is_convex(p2, p3, p)
        } else {
            TpplPartition::is_convex(p1, p2, p) || TpplPartition::is_convex(p2, p3, p)
        }
    }

    pub fn triangulate_mono(inpolys: &mut Vec<TpplPoly>, triangles: &mut Vec<TpplPoly>) -> bool {
        let mut monotone = Vec::new();
        for poly in inpolys.iter() {
            if !TpplPartition::triangulate_monotone(poly, &mut monotone) {
                return false;
            }
        }

        triangles.extend(monotone);
        true
    }

    pub fn triangulate_monotone(in_poly: &TpplPoly, triangles: &mut Vec<TpplPoly>) -> bool {
        let points = in_poly.points.clone();

        if points.len() < 3 {
            return false;
        }

        let mut top_index = 0;
        let mut bottom_index = 0;
        for i in 0..points.len() {
            if TpplPartition::below(&points[i], &points[bottom_index]) {
                bottom_index = i;
            }
            if TpplPartition::below(&points[top_index], &points[i]) {
                top_index = i;
            }
        }

        let mut left_chain = Vec::new();
        let mut right_chain = Vec::new();
        let mut current = top_index;
        while current != bottom_index {
            left_chain.push(current);
            current = (current + 1) % points.len();
        }
        left_chain.push(bottom_index);

        current = top_index;
        while current != bottom_index {
            right_chain.push(current);
            current = if current == 0 {
                points.len() - 1
            } else {
                current - 1
            };
        }
        right_chain.push(bottom_index);

        if left_chain.len() <= 2 || right_chain.len() <= 2 {
            return false;
        }

        let mut stack = vec![left_chain[0], left_chain[1]];
        let mut left = true;
        let mut chain = left_chain.as_slice();
        if TpplPartition::below(&points[left_chain[1]], &points[right_chain[1]]) {
            chain = right_chain.as_slice();
            left = false;
        }

        for i in 2..chain.len() - 1 {
            let current_point = chain[i];

            while stack.len() > 1 {
                let last = stack[stack.len() - 1];
                let second_last = stack[stack.len() - 2];

                if left {
                    if !TpplPartition::is_convex(&points[second_last], &points[last], &points[current_point]) {
                        break;
                    }
                } else {
                    if !TpplPartition::is_convex(&points[current_point], &points[last], &points[second_last]) {
                        break;
                    }
                }
                stack.pop();
                triangles.push(TpplPoly {
                    hole: false,
                    points: vec![
                        points[second_last],
                        points[last],
                        points[current_point],
                    ],
                });
            }

            stack.push(current_point);
        }

        let current_point = chain[chain.len() - 1];

        for _ in 0..stack.len() - 1 {
            let last = stack[stack.len() - 1];
            let second_last = stack[stack.len() - 2];
            if left {
                triangles.push(TpplPoly {
                    hole: false,
                    points: vec![points[second_last], points[last], points[current_point]],
                });
            } else {
                triangles.push(TpplPoly {
                    hole: false,
                    points: vec![points[current_point], points[last], points[second_last]],
                });
            }
            stack.pop();
        }

        true
    }

    pub fn below(p1: &TpplPoint, p2: &TpplPoint) -> bool {
        p1.y < p2.y || (p1.y == p2.y && p1.x < p2.x)
    }
}

