#[derive(Clone, Debug, Default, PartialEq)]
struct TPPLPoint {
    x: f64,
    y: f64,
}

impl TPPLPoint {
    fn new(x: f64, y: f64) -> Self {
        Self { x, y }
    }

    // Subtraction
    fn sub(&self, other: &Self) -> Self {
        TPPLPoint {
            x: self.x - other.x,
            y: self.y - other.y,
        }
    }

    // Division by scalar
    fn div_by_scalar(&self, scalar: f64) -> Self {
        TPPLPoint {
            x: self.x / scalar,
            y: self.y / scalar,
        }
    }
}

type TPPLPolyList = Vec<TPPLPoly>;
type TpplFloat = f64;

#[derive(Clone, Copy, Debug, PartialEq)]
enum TPPLOrientation {
    TpplOrientationCcw,
    TpplOrientationCw,
    TpplOrientationNone,
}

#[derive(Clone)]
struct TPPLPoly {
    hole: bool,
    numpoints: usize,
    points: Option<Vec<TPPLPoint>>,
}

impl TPPLPoly {
    fn new() -> Self {
        Self {
            hole: false,
            numpoints: 0,
            points: None,
        }
    }

    fn clear(&mut self) {
        self.hole = false;
        self.numpoints = 0;
        self.points = None;
    }

    fn init(&mut self, numpoints: usize) {
        self.clear();
        self.numpoints = numpoints;
        self.points = Some(vec![TPPLPoint::default(); numpoints]);
    }

    fn triangle(&mut self, p1: TPPLPoint, p2: TPPLPoint, p3: TPPLPoint) {
        self.init(3);
        if let Some(ref mut points) = self.points {
            points[0] = p1;
            points[1] = p2;
            points[2] = p3;
        }
    }

    fn get_orientation(&self) -> TPPLOrientation {
        let mut area = 0.0;
        if let Some(ref points) = self.points {
            for i1 in 0..self.numpoints {
                let i2 = if i1 + 1 == self.numpoints { 0 } else { i1 + 1 };
                area += points[i1].x * points[i2].y - points[i1].y * points[i2].x;
            }
        }

        if area > 0.0 {
            TPPLOrientation::TpplOrientationCcw
        } else if area < 0.0 {
            TPPLOrientation::TpplOrientationCw
        } else {
            TPPLOrientation::TpplOrientationNone
        }
    }

    fn set_orientation(&mut self, orientation: TPPLOrientation) {
        let polyorientation = self.get_orientation();
        if polyorientation != TPPLOrientation::TpplOrientationNone && polyorientation != orientation {
            self.invert();
        }
    }

    fn invert(&mut self) {
        if let Some(ref mut points) = self.points {
            points.reverse();
        }
    }

    fn valid(&self) -> bool {
        self.points.is_some() && self.numpoints >= 3
    }

    fn get_point(&self, index: usize) -> TPPLPoint {
        self.points.as_ref().unwrap()[index].clone()
    }

    fn get_num_points(&self) -> usize {
        self.numpoints
    }

    fn is_hole(&self) -> bool {
        self.hole
    }
}

#[allow(non_snake_case)]
struct TPPLPartition;

impl TPPLPartition {
    fn normalize(p: &TPPLPoint) -> TPPLPoint {
        let n = (p.x * p.x + p.y * p.y).sqrt();
        if n != 0.0 {
            p.div_by_scalar(n)
        } else {
            TPPLPoint::new(0.0, 0.0)
        }
    }

    fn distance(p1: &TPPLPoint, p2: &TPPLPoint) -> TpplFloat {
        let dx = p2.x - p1.x;
        let dy = p2.y - p1.y;
        (dx * dx + dy * dy).sqrt()
    }

    fn intersects(p11: &TPPLPoint, p12: &TPPLPoint, p21: &TPPLPoint, p22: &TPPLPoint) -> bool {
        if p11 == p21 || p11 == p22 || p12 == p21 || p12 == p22 {
            return false;
        }

        let v1ort = TPPLPoint::new(p12.y - p11.y, p11.x - p12.x);
        let v2ort = TPPLPoint::new(p22.y - p21.y, p21.x - p22.x);

        let v = p21.sub(p11);
        let dot21 = v.x * v1ort.x + v.y * v1ort.y;
        let v = p22.sub(p11);
        let dot22 = v.x * v1ort.x + v.y * v1ort.y;

        let v = p11.sub(p21);
        let dot11 = v.x * v2ort.x + v.y * v2ort.y;
        let v = p12.sub(p21);
        let dot12 = v.x * v2ort.x + v.y * v2ort.y;

        dot11 * dot12 <= 0.0 && dot21 * dot22 <= 0.0
    }

    fn remove_holes(inpolys: &mut TPPLPolyList, outpolys: &mut TPPLPolyList) -> bool {
        let mut polys = inpolys.clone();
        loop {
            if let Some(hole_pos) = polys.iter().position(|p| p.is_hole()) {
                let holeiter = polys.remove(hole_pos);
                let holepointindex = holeiter
                    .points
                    .as_ref()
                    .unwrap()
                    .iter()
                    .enumerate()
                    .reduce(|a, b| if a.1.x > b.1.x { a } else { b })
                    .map(|(idx, _)| idx)
                    .unwrap();

                let mut pointfound = false;
                let holepoint = holeiter.get_point(holepointindex);
                let mut bestpolypoint = TPPLPoint::default();
                let mut poly_pos = 0;

                for i in 0..polys.len() {
                    let iter = &polys[i];
                    if !pointfound && iter.is_hole() {
                        continue;
                    }
                    for i_point in 0..iter.get_num_points() {
                        if iter.get_point(i_point).x <= holepoint.x {
                            continue;
                        }

                        let i_prev = (i_point + iter.get_num_points() - 1) % iter.get_num_points();
                        let i_next = (i_point + 1) % iter.get_num_points();

                        if !Self::in_cone(&iter.get_point(i_prev), &iter.get_point(i_point), &iter.get_point(i_next), &holepoint) {
                            continue;
                        }

                        let polypoint = iter.get_point(i_point);
                        if !pointfound || Self::distance(&holepoint, &polypoint) < Self::distance(&holepoint, &bestpolypoint) {
                            let mut pointvisible = true;

                            for iter2 in &polys {
                                if iter2.is_hole() {
                                    continue;
                                }

                                for i2 in 0..iter2.get_num_points() {
                                    let linep1 = iter2.get_point(i2);
                                    let linep2 = iter2.get_point((i2 + 1) % iter2.get_num_points());
                                    if Self::intersects(&holepoint, &polypoint, &linep1, &linep2) {
                                        pointvisible = false;
                                        break;
                                    }
                                }

                                if !pointvisible {
                                    break;
                                }
                            }

                            if pointvisible {
                                bestpolypoint = polypoint.clone();
                                poly_pos = i;
                                pointfound = true;
                            }
                        }
                    }
                }

                if !pointfound {
                    return false;
                }

                let polyiter = polys[poly_pos].clone();
                let mut newpoly = TPPLPoly::new();
                newpoly.init(holeiter.get_num_points() + polyiter.get_num_points() + 2);

                let mut i = 0;
                for idx1 in 0..=holepointindex {
                    if let Some(ref mut points) = newpoly.points {
                        points[i] = holeiter.get_point(idx1);
                        i += 1;
                    }
                }

                for idx2 in 0..holeiter.get_num_points() {
                    if let Some(ref mut points) = newpoly.points {
                        points[i] = holeiter.get_point((idx2 + holepointindex) % holeiter.get_num_points());
                        i += 1;
                    }
                }

                for idx3 in 0..polyiter.get_num_points() {
                    if let Some(ref mut points) = newpoly.points {
                        points[i] = polyiter.get_point(idx3);
                        i += 1;
                    }
                }

                polys.push(newpoly);
            } else {
                outpolys.extend_from_slice(&polys);
                return true;
            }
        }
    }

    fn in_cone(p1: &TPPLPoint, p2: &TPPLPoint, p3: &TPPLPoint, p: &TPPLPoint) -> bool {
        if Self::is_convex(p1, p2, p3) {
            Self::is_convex(p1, p2, p) && Self::is_convex(p2, p3, p)
        } else {
            Self::is_convex(p1, p2, p) || Self::is_convex(p2, p3, p)
        }
    }

    fn is_convex(p1: &TPPLPoint, p2: &TPPLPoint, p3: &TPPLPoint) -> bool {
        (p3.y - p1.y) * (p2.x - p1.x) - (p3.x - p1.x) * (p2.y - p1.y) > 0.0
    }
}

