            area += self.points[i1].x * self.points[i2].y - self.points[i1].y * self.points[i2].x;
        }
        if area > 0.0 {
            TPPLOrientation::CCW
        } else if area < 0.0 {
            TPPLOrientation::CW
        } else {
            TPPLOrientation::NONE
        }
    }

    fn set_orientation(&mut self, orientation: TPPLOrientation) {
        let polyorientation = self.get_orientation();
        if polyorientation != TPPLOrientation::NONE && polyorientation != orientation {
