use std::f32;

#[derive(Clone, Copy)]
struct Pixel {
    r: u8,
    g: u8,
    b: u8,
}

pub struct Image {
    width: usize,
    height: usize,
    data: Vec<u8>,
}

impl Image {
    pub fn new() -> Self {
        Image {
            width: 0,
            height: 0,
            data: Vec::new(),
        }
    }

    pub fn with_dimensions(width: usize, height: usize) -> Self {
        let data = vec![0; 3 * width * height];
        Image { width, height, data }
    }

    pub fn from_image(src: &Image) -> Self {
        Image {
            width: src.width,
            height: src.height,
            data: src.data.clone(),
        }
    }

    pub fn assign_from(&mut self, src: &Image) {
        self.width = src.width;
        self.height = src.height;
        self.data = src.data.clone();
    }

    pub fn init(&mut self, width: usize, height: usize) {
        self.width = width;
        self.height = height;
        self.data = vec![0; 3 * width * height];
    }

    pub fn get_mean_gray(&self) -> u8 {
        let mut sum = 0u64;
        for i in 0..self.height {
            for j in 0..self.width {
                sum += self.get_pixel_gray(j, i) as u64;
            }
        }
        (sum / (self.width * self.height) as u64) as u8
    }

    pub fn binarize(&mut self, threshold: u8) {
        for i in 0..self.height {
            for j in 0..self.width {
                let c = self.get_pixel_gray(j, i);
                if c > threshold {
                    self.set_pixel_gray(j, i, 255);
                } else {
                    self.set_pixel_gray(j, i, 0);
                }
            }
        }
    }

    pub fn flip_horizontal(&mut self) {
        let mut new_data = vec![0; self.height * self.width * 3];
        for i in 0..self.height {
            for j in 0..self.width {
                let index1 = 3 * (i * self.width + j);
                let index2 = 3 * (i * self.width + self.width - j - 1);
                for k in 0..3 {
                    new_data[index1 + k] = self.data[index2 + k];
                }
            }
        }
        self.data = new_data;
    }

    pub fn flip_vertical(&mut self) {
        let mut new_data = vec![0; self.height * self.width * 3];
        for i in 0..self.height {
            for j in 0..self.width {
                let index1 = 3 * (i * self.width + j);
                let index2 = 3 * ((self.height - i - 1) * self.width + j);
                for k in 0..3 {
                    new_data[index1 + k] = self.data[index2 + k];
                }
            }
        }
        self.data = new_data;
    }

    pub fn get_pixel_bilinear(&self, x: f32, y: f32) -> Pixel {
        let zero_pixel = Pixel{ r: 0, g: 0, b: 0};
        if x < 0.0 || y < 0.0 || x > (self.width - 1) as f32 || y > (self.height - 1) as f32 {
            return zero_pixel;
        }

        let x1 = x.floor() as usize;
        let y1 = y.floor() as usize;
        let dx = x - x1 as f32;
        let dy = y - y1 as f32;

        let c1 = self.get_pixel_color(x1, y1);
        let c2 = self.get_pixel_color(x1 + 1, y1);
        let c3 = self.get_pixel_color(x1, y1 + 1);
        let c4 = self.get_pixel_color(x1 + 1, y1 + 1);

        Pixel {
            r: Self::round(Self::interpolate(c1.r, c2.r, c3.r, c4.r, dx, dy)) as u8,
            g: Self::round(Self::interpolate(c1.g, c2.g, c3.g, c4.g, dx, dy)) as u8,
            b: Self::round(Self::interpolate(c1.b, c2.b, c3.b, c4.b, dx, dy)) as u8,
        }
    }

    fn interpolate(x1: u8, x2: u8, x3: u8, x4: u8, dx: f32, dy: f32) -> f32 {
        let x5 = x2 as f32 * dx + x1 as f32 * (1.0 - dx);
        let x6 = x4 as f32 * dx + x3 as f32 * (1.0 - dx);
        x6 * dy + x5 * (1.0 - dy)
    }

    fn round(x: f32) -> usize {
        if (x - x.floor()) < 0.5 {
            x.floor() as usize
        } else {
            x.ceil() as usize
        }
    }

    pub fn get_histogram_gray(&self) -> [usize; 256] {
        let mut histogram = [0; 256];
        for i in 0..self.height {
            for j in 0..self.width {
                histogram[self.get_pixel_gray(j, i) as usize] += 1;
            }
        }
        histogram
    }

    pub fn invert(&mut self) {
        let n = self.width * self.height * 3;
        for i in 0..n {
            self.data[i] = 255 - self.data[i];
        }
    }

    pub fn crop(&self, posx: usize, posy: usize, width: usize, height: usize) -> Image {
        let mut result_img = Image::with_dimensions(width, height);
        for i in 0..height {
            for j in 0..width {
                let rgb = self.get_pixel_color(j + posx, i + posy);
                result_img.set_pixel_color(j, i, rgb);
            }
        }
        result_img
    }

    pub fn resize(&self, factor: usize) -> Image {
        let new_width = self.width / factor;
        let new_height = self.height / factor;
        let factor2 = (factor * factor) as f32;

        let mut result_img = Image::with_dimensions(new_width, new_height);
        for i in 0..new_height {
            for j in 0..new_width {
                let (minx, miny) = (j * factor, i * factor);
                let (maxx, maxy) = (minx + factor, miny + factor);

                let mut sum_r = 0;
                let mut sum_g = 0;
                let mut sum_b = 0;

                for i2 in miny..maxy {
                    for j2 in minx..maxx {
                        let rgb = self.get_pixel_color(j2, i2);
                        sum_r += rgb.r as usize;
                        sum_g += rgb.g as usize;
                        sum_b += rgb.b as usize;
                    }
                }
                result_img.set_pixel_color(j, i, Pixel {
                    r: Self::round(sum_r as f32 / factor2) as u8,
                    g: Self::round(sum_g as f32 / factor2) as u8,
                    b: Self::round(sum_b as f32 / factor2) as u8,
                });
            }
        }
        result_img
    }

    pub fn filter(&self, filter: &[f32], filter_width: usize, filter_height: usize) -> Image {
        let mut ret = Image::with_dimensions(self.width, self.height);
        let fox = filter_width / 2;
        let foy = filter_height / 2;

        for i1 in 0..self.height {
            for j1 in 0..self.width {
                let mut sumr = 0.0;
                let mut sumg = 0.0;
                let mut sumb = 0.0;

                for i2 in 0..filter_height {
                    for j2 in 0..filter_width {
                        let (x, y) = (
                            isize::clamp(j1 as isize + j2 as isize - fox as isize, 0, self.width as isize - 1) as usize,
                            isize::clamp(i1 as isize + i2 as isize - foy as isize, 0, self.height as isize - 1) as usize,
                        );

                        let offset3 = i2 * filter_width + j2;
                        let offset2 = (y * self.width + x) * 3;

                        sumr += self.data[offset2] as f32 * filter[offset3];
                        sumg += self.data[offset2 + 1] as f32 * filter[offset3];
                        sumb += self.data[offset2 + 2] as f32 * filter[offset3];
                    }
                }
                let offset1 = (i1 * self.width + j1) * 3;
                ret.data[offset1] = Self::round(sumr) as u8;
                ret.data[offset1 + 1] = Self::round(sumg) as u8;
                ret.data[offset1 + 2] = Self::round(sumb) as u8;
            }
        }
        ret
    }

    pub fn gauss_blur(&self, sigma: f32, mut mask_size: usize) -> Image {
        if mask_size == 0 {
            mask_size = Self::round(sigma) * 2 * 2 + 1;
        }

        let fsize = mask_size * mask_size;
        let mut filter = vec![0.0; fsize];
        let fo = mask_size / 2;
        let pi = f32::consts::PI;

        for i in 0..mask_size {
            for j in 0..mask_size {
                let x = i as isize - fo as isize;
                let y = j as isize - fo as isize;
                filter[i * mask_size + j] = (1.0 / (2.0 * pi * sigma)) * (-((x * x + y * y) as f32) / (2.0 * sigma * sigma)).exp();
            }
        }

        let sum: f32 = filter.iter().sum();
        for v in &mut filter {
            *v /= sum;
        }

        self.filter(&filter, mask_size, mask_size)
    }

    pub fn clear(&mut self, color: Pixel) {
        for y in 0..self.height {
            for x in 0..self.width {
                self.set_pixel_color(x, y, color);
            }
        }
    }

    pub fn draw_line(&mut self, x1: isize, y1: isize, x2: isize, y2: isize, color: Pixel) {
        let dx = (x2 - x1).abs();
        let dy = (y2 - y1).abs();

        if dx > dy {
            if x1 > x2 {
                self.draw_line_low(x2, y2, x1, y1, color);
            } else {
                self.draw_line_low(x1, y1, x2, y2, color);
            }
        } else {
            if y1 > y2 {
                self.draw_line_high(x2, y2, x1, y1, color);
            } else {
                self.draw_line_high(x1, y1, x2, y2, color);
            }
        }
    }

    fn draw_line_low(&mut self, x1: isize, y1: isize, x2: isize, y2: isize, color: Pixel) {
        let dx = x2 - x1;
        let dy = y2 - y1;
        let mut d = 2 * dy - dx;
        let mut y = y1;
        for x in x1..=x2 {
            self.set_pixel_color(x as usize, y as usize, color);
            if d > 0 {
                y += 1;
                d -= 2 * dx;
            }
            d += 2 * dy;
        }
    }

    fn draw_line_high(&mut self, x1: isize, y1: isize, x2: isize, y2: isize, color: Pixel) {
        let dx = x2 - x1;
        let dy = y2 - y1;
        let mut d = 2 * dx - dy;
        let mut x = x1;
        for y in y1..=y2 {
            self.set_pixel_color(x as usize, y as usize, color);
            if d > 0 {
                x += 1;
                d -= 2 * dy;
            }
            d += 2 * dx;
        }
    }

    fn get_pixel_gray(&self, x: usize, y: usize) -> u8 {
        let base = (y * self.width + x) * 3;
        let r = self.data[base] as usize;
        let g = self.data[base + 1] as usize;
        let b = self.data[base + 2] as usize;
        ((r + g + b) / 3) as u8
    }

    fn set_pixel_gray(&mut self, x: usize, y: usize, gray: u8) {
        let base = (y * self.width + x) * 3;
        self.data[base] = gray;
        self.data[base + 1] = gray;
        self.data[base + 2] = gray;
    }

    fn get_pixel_color(&self, x: usize, y: usize) -> Pixel {
        let base = (y * self.width + x) * 3;
        Pixel {
            r: self.data[base],
            g: self.data[base + 1],
            b: self.data[base + 2],
        }
    }

    fn set_pixel_color(&mut self, x: usize, y: usize, color: Pixel) {
        let base = (y * self.width + x) * 3;
        self.data[base] = color.r;
        self.data[base + 1] = color.g;
        self.data[base + 2] = color.b;
    }
}

