        for i in 0..self.height {
            for j in 0..self.width {
                let index1 = 3 * (i * self.width + j);
                let index2 = 3 * ((self.height - i - 1) * self.width + j);
                new_data[index1..index1 + 3].copy_from_slice(&self.data[index2..index2 + 3]);
            }
        }
        self.data = new_data;
    }

    fn get_pixel_bilinear(&self, x: f32, y: f32) -> Pixel {
        if x < 0.0 || y < 0.0 || x > (self.width as f32 - 1.0) || y > (self.height as f32 - 1.0) {
            return Pixel { r: 0, g: 0, b: 0 };
        }

        let x1 = x.floor() as usize;
        let y1 = y.floor() as usize;
        let dx = x - x1 as f32;
        let dy = y - y1 as f32;

        let c1 = self.get_pixel_color(x1, y1);
        let c2 = self.get_pixel_color(x1 + 1, y1);
        let c3 = self.get_pixel_color(x1, y1 + 1);
        let c4 = self.get_pixel_color(x1 + 1, y1 + 1);

        Pixel {
            r: Self::round(Image::interpolate(c1.r, c2.r, c3.r, c4.r, dx, dy)) as u8,
            g: Self::round(Image::interpolate(c1.g, c2.g, c3.g, c4.g, dx, dy)) as u8,
            b: Self::round(Image::interpolate(c1.b, c2.b, c3.b, c4.b, dx, dy)) as u8,
        }
    }

    fn interpolate(x1: u8, x2: u8, x3: u8, x4: u8, dx: f32, dy: f32) -> f32 {
        let x1 = x1 as f32;
        let x2 = x2 as f32;
        let x3 = x3 as f32;
        let x4 = x4 as f32;
        let x5 = x2 * dx + x1 * (1.0 - dx);
        let x6 = x4 * dx + x3 * (1.0 - dx);
        x6 * dy + x5 * (1.0 - dy)
    }

    fn round(x: f32) -> usize {
        if (x - x.floor()) < 0.5 {
            x.floor() as usize
        } else {
            x.ceil() as usize
        }
    }

    fn get_histogram_gray(&self) -> [u64; 256] {
        let mut histogram = [0u64; 256];
        for i in 0..self.height {
            for j in 0..self.width {
                histogram[self.get_pixel_gray(j, i) as usize] += 1;
            }
        }
        histogram
    }

    pub fn invert(&mut self) {
        for pixel in &mut self.data {
            *pixel = 255 - *pixel;
        }
    }

    pub fn crop(&self, posx: usize, posy: usize, width: usize, height: usize) -> Image {
        let mut result_img = Image::with_size(width, height);
        for i in 0..height {
            for j in 0..width {
                let rgb = self.get_pixel_color(j + posx, i + posy);
                result_img.set_pixel_color(j, i, rgb);
            }
        }
        result_img
    }

    pub fn resize(&self, factor: usize) -> Image {
        let width = self.width / factor;
        let height = self.height / factor;
        let factor2 = factor * factor;

        let mut result_img = Image::with_size(width, height);

        for i in 0..height {
            for j in 0..width {
                let minx = j * factor;
                let miny = i * factor;
                let maxx = minx + factor;
                let maxy = miny + factor;

                let (mut sum_r, mut sum_g, mut sum_b) = (0, 0, 0);

                for i2 in miny..maxy {
                    for j2 in minx..maxx {
                        let rgb = self.get_pixel_color(j2, i2);
                        sum_r += rgb.r as usize;
                        sum_g += rgb.g as usize;
                        sum_b += rgb.b as usize;
                    }
                }

                result_img.set_pixel_color(j, i, Pixel {
                    r: Self::round(sum_r as f32 / factor2 as f32) as u8,
                    g: Self::round(sum_g as f32 / factor2 as f32) as u8,
                    b: Self::round(sum_b as f32 / factor2 as f32) as u8,
                });
            }
        }
        result_img
    }

    pub fn filter(&self, filter: &[f32], filter_width: usize, filter_height: usize) -> Image {
        let mut result_img = Image::with_size(self.width, self.height);
        let fox = filter_width / 2;
        let foy = filter_height / 2;

        for i1 in 0..self.height {
            for j1 in 0..self.width {
                let mut sum_r = 0.0;
                let mut sum_g = 0.0;
                let mut sum_b = 0.0;

                for i2 in -(foy as isize)..=(foy as isize) {
                    for j2 in -(fox as isize)..=(fox as isize) {
                        let x = min(max((j1 as isize + j2) as usize, 0), self.width - 1);
                        let y = min(max((i1 as isize + i2) as usize, 0), self.height - 1);
                        let offset = ((y * self.width + x) * 3) as isize;
                        let f_index = ((i2 + foy as isize) * filter_width as isize + j2 + fox as isize) as usize;
                        let data_offset = offset as usize;

                        sum_r += self.data[data_offset] as f32 * filter[f_index];
                        sum_g += self.data[data_offset + 1] as f32 * filter[f_index];
                        sum_b += self.data[data_offset + 2] as f32 * filter[f_index];
                    }
                }
                let offset1 = (i1 * self.width + j1) * 3;
                result_img.data[offset1] = Self::round(sum_r) as u8;
                result_img.data[offset1 + 1] = Self::round(sum_g) as u8;
                result_img.data[offset1 + 2] = Self::round(sum_b) as u8;
            }
        }
        result_img
    }

    pub fn gauss_blur(&self, sigma: f32, mask_size: usize) -> Image {
        let mask_size = if mask_size == 0 {
            (sigma.round() as usize) * 2 * 2 + 1
        } else {
            mask_size
        };

        let fs = mask_size * mask_size;
        let fo = mask_size / 2;
        let mut filter = vec![0.0; fs];

        for i in -(fo as isize)..=(fo as isize) {
            for j in -(fo as isize)..=(fo as isize) {
                let index = ((i + fo as isize) as usize * mask_size + (j + fo as isize) as usize) as usize;
                filter[index] =
                    1.0 / (2.0 * PI * sigma.powi(2)) * (-((i * i + j * j) as f32 / (2.0 * sigma.powi(2)))).exp();
            }
        }

        let sum: f32 = filter.iter().sum();
        for val in filter.iter_mut() {
            *val /= sum;
        }

        self.filter(&filter, mask_size, mask_size)
    }

    pub fn clear(&mut self, color: Pixel) {
        for y in 0..self.height {
            for x in 0..self.width {
                self.set_pixel_color(x, y, color);
            }
        }
    }

    pub fn draw_line(&mut self, x1: isize, y1: isize, x2: isize, y2: isize, color: Pixel) {
        let dx = (x2 - x1).abs();
        let dy = (y2 - y1).abs();
        if dx > dy {
            if x2 > x1 {
                for i in x1..=x2 {
                    let y = (y1 as f32 + (y2 - y1) as f32 / (x2 - x1) as f32 * (i - x1) as f32).round() as isize;
                    self.set_pixel_color(i as usize, y as usize, color);
                }
            } else {
                for i in x2..=x1 {
                    let y = (y2 as f32 + (y1 - y2) as f32 / (x1 - x2) as f32 * (i - x2) as f32).round() as isize;
                    self.set_pixel_color(i as usize, y as usize, color);
                }
            }
        } else {
            if y2 > y1 {
                for i in y1..=y2 {
                    let x = (x1 as f32 + (x2 - x1) as f32 / (y2 - y1) as f32 * (i - y1) as f32).round() as isize;
                    self.set_pixel_color(x as usize, i as usize, color);
                }
            } else {
                for i in y2..=y1 {
                    let x = (x2 as f32 + (x1 - x2) as f32 / (y1 - y2) as f32 * (i - y2) as f32).round() as isize;
                    self.set_pixel_color(x as usize, i as usize, color);
                }
            }
        }
    }

    fn get_pixel_color(&self, x: usize, y: usize) -> Pixel {
        let i = (y * self.width + x) * 3;
        Pixel {
            r: self.data[i],
            g: self.data[i + 1],
            b: self.data[i + 2],
        }
    }

    fn set_pixel_color(&mut self, x: usize, y: usize, pixel: Pixel) {
        let i = (y * self.width + x) * 3;
        self.data[i] = pixel.r;
        self.data[i + 1] = pixel.g;
        self.data[i + 2] = pixel.b;
    }

    fn get_pixel_gray(&self, x: usize, y: usize) -> u8 {
        let pixel = self.get_pixel_color(x, y);
        (0.299 * pixel.r as f32 + 0.587 * pixel.g as f32 + 0.114 * pixel.b as f32) as u8
    }

    fn set_pixel_gray(&mut self, x: usize, y: usize, gray: u8) {
        self.set_pixel_color(x, y, Pixel { r: gray, g: gray, b: gray })
    }
}

