pub struct Pixel {
    pub r: u8,
    pub g: u8,
    pub b: u8,
}

impl Clone for Pixel {
    fn clone(&self) -> Self {
        Pixel { r: self.r, g: self.g, b: self.b }
    }
}

pub struct Image {
    width: usize,
    height: usize,
    data: Option<Box<[u8]>>,
}

impl Image {
    pub fn new() -> Self {
        Image {
            width: 0,
            height: 0,
            data: None,
        }
    }

    pub fn with_size(width: usize, height: usize) -> Self {
        let data_size = 3 * width * height;
        let data = vec![0; data_size].into_boxed_slice();
        Image {
            width,
            height,
            data: Some(data),
        }
    }

    pub fn from(src: &Image) -> Self {
        let data_size = 3 * src.width * src.height;
        let data = src.data.as_ref().map(|d| {
            let mut new_data = vec![0; data_size].into_boxed_slice();
            new_data.copy_from_slice(d);
            new_data
        });
        Image {
            width: src.width,
            height: src.height,
            data,
        }
    }

    pub fn init(&mut self, width: usize, height: usize) {
        let data_size = 3 * width * height;
        let data = vec![0; data_size].into_boxed_slice();
        self.width = width;
        self.height = height;
        self.data = Some(data);
    }

    pub fn get_mean_gray(&self) -> u8 {
        let mut sum = 0;
        let data = self.data.as_ref().unwrap();
        for i in 0..self.height {
            for j in 0..self.width {
                sum += self.get_pixel_gray(j, i) as usize;
            }
        }
        (sum / (self.width * self.height)) as u8
    }

    pub fn binarize(&mut self, threshold: u8) {
        let data = self.data.as_mut().unwrap();
        for i in 0..self.height {
            for j in 0..self.width {
                let c = self.get_pixel_gray(j, i);
                if c > threshold {
                    self.set_pixel_gray(j, i, 255);
                } else {
                    self.set_pixel_gray(j, i, 0);
                }
            }
        }
    }

    pub fn flip_horizontal(&mut self) {
        let data_size = self.height * self.width * 3;
        let mut new_data = vec![0; data_size].into_boxed_slice();
        let data = self.data.as_ref().unwrap();

        for i in 0..self.height {
            for j in 0..self.width {
                let index1 = 3 * (i * self.width + j);
                let index2 = 3 * (i * self.width + self.width - j - 1);
                new_data[index1..index1 + 3].copy_from_slice(&data[index2..index2 + 3]);
            }
        }
        self.data = Some(new_data);
    }

    pub fn flip_vertical(&mut self) {
        let data_size = self.height * self.width * 3;
        let mut new_data = vec![0; data_size].into_boxed_slice();
        let data = self.data.as_ref().unwrap();

        for i in 0..self.height {
            for j in 0..self.width {
                let index1 = 3 * (i * self.width + j);
                let index2 = 3 * ((self.height - i - 1) * self.width + j);
                new_data[index1..index1 + 3].copy_from_slice(&data[index2..index2 + 3]);
            }
        }
        self.data = Some(new_data);
    }

    pub fn get_pixel_bilinear(&self, x: f32, y: f32) -> Pixel {
        let mut c = Pixel { r: 0, g: 0, b: 0 };
        if x < 0.0 || y < 0.0 || x > (self.width as f32 - 1.0) || y > (self.height as f32 - 1.0) {
            return c;
        }
        let x1 = x.floor() as usize;
        let y1 = y.floor() as usize;
        let dx = x - x1 as f32;
        let dy = y - y1 as f32;
        let c1 = self.get_pixel_color(x1, y1);
        let c2 = self.get_pixel_color(x1 + 1, y1);
        let c3 = self.get_pixel_color(x1, y1 + 1);
        let c4 = self.get_pixel_color(x1 + 1, y1 + 1);
        c.r = Self::round(Self::interpolate(c1.r as f32, c2.r as f32, c3.r as f32, c4.r as f32, dx, dy)) as u8;
        c.g = Self::round(Self::interpolate(c1.g as f32, c2.g as f32, c3.g as f32, c4.g as f32, dx, dy)) as u8;
        c.b = Self::round(Self::interpolate(c1.b as f32, c2.b as f32, c3.b as f32, c4.b as f32, dx, dy)) as u8;
        c
    }

    fn interpolate(x1: f32, x2: f32, x3: f32, x4: f32, dx: f32, dy: f32) -> f32 {
        let x5 = x2 * dx + x1 * (1.0 - dx);
        let x6 = x4 * dx + x3 * (1.0 - dx);
        x6 * dy + x5 * (1.0 - dy)
    }

    fn round(x: f32) -> f32 {
        if (x - x.floor()) < 0.5 {
            x.floor()
        } else {
            x.ceil()
        }
    }

    pub fn get_histogram_gray(&self, histogram: &mut [usize; 256]) {
        histogram.fill(0);
        for i in 0..self.height {
            for j in 0..self.width {
                histogram[self.get_pixel_gray(j, i) as usize] += 1;
            }
        }
    }

    pub fn invert(&mut self) {
        if let Some(data) = self.data.as_mut() {
            for byte in data.iter_mut() {
                *byte = 255 - *byte;
            }
        }
    }

    pub fn crop(&self, posx: usize, posy: usize, width: usize, height: usize) -> Image {
        let mut result_img = Image::with_size(width, height);
        for i in 0..height {
            for j in 0..width {
                let rgb = self.get_pixel_color(j + posx, i + posy);
                result_img.set_pixel_color(j, i, rgb);
            }
        }
        result_img
    }

    pub fn resize(&self, factor: usize) -> Image {
        let width = self.width / factor;
        let height = self.height / factor;
        let factor_squared = factor * factor;
        let mut result_img = Image::with_size(width, height);

        for i in 0..height {
            for j in 0..width {
                let mut sum_r = 0;
                let mut sum_g = 0;
                let mut sum_b = 0;

                let base_y = i * factor;
                let base_x = j * factor;

                for y_offset in 0..factor {
                    for x_offset in 0..factor {
                        let rgb = self.get_pixel_color(base_x + x_offset, base_y + y_offset);
                        sum_r += rgb.r as usize;
                        sum_g += rgb.g as usize;
                        sum_b += rgb.b as usize;
                    }
                }

                let rgb = Pixel {
                    r: (sum_r / factor_squared) as u8,
                    g: (sum_g / factor_squared) as u8,
                    b: (sum_b / factor_squared) as u8,
                };
                result_img.set_pixel_color(j, i, rgb);
            }
        }
        result_img
    }

    pub fn filter(&self, filter: &[f32], filter_width: usize, filter_height: usize) -> Image {
        let mut ret = Image::with_size(self.width, self.height);
        let fox = filter_width as isize / 2;
        let foy = filter_height as isize / 2;

        let data = self.data.as_ref().unwrap();
        let ret_data = ret.data.as_mut().unwrap();

        for i in 0..self.height {
            for j in 0..self.width {
                let mut sum_r = 0.0;
                let mut sum_g = 0.0;
                let mut sum_b = 0.0;

                for ky in -foy..=foy {
                    for kx in -fox..=fox {
                        let x = (j as isize + kx).clamp(0, self.width as isize - 1) as usize;
                        let y = (i as isize + ky).clamp(0, self.height as isize - 1) as usize;

                        let pixel_index = (y * self.width + x) * 3;
                        let filter_index = (ky + foy) as usize * filter_width + (kx + fox) as usize;
                        let filter_value = filter[filter_index];

                        sum_r += data[pixel_index] as f32 * filter_value;
                        sum_g += data[pixel_index + 1] as f32 * filter_value;
                        sum_b += data[pixel_index + 2] as f32 * filter_value;
                    }
                }

                let pixel_index = (i * self.width + j) * 3;
                ret_data[pixel_index] = Self::round(sum_r) as u8;
                ret_data[pixel_index + 1] = Self::round(sum_g) as u8;
                ret_data[pixel_index + 2] = Self::round(sum_b) as u8;
            }
        }

        ret
    }

    pub fn gauss_blur(&self, sigma: f32, mask_size: Option<usize>) -> Image {
        let mask_size = mask_size.unwrap_or((sigma.round() as usize * 2) * 2 + 1);
        let fs_size = mask_size * mask_size;
        let fo = mask_size / 2;
        let mut filter = vec![0.0; fs_size];

        let two_pi_sigma = 2.0 * std::f32::consts::PI * sigma;
        for i in 0..mask_size {
            for j in 0..mask_size {
                let x = (i as isize - fo as isize) as f32;
                let y = (j as isize - fo as isize) as f32;
                filter[i * mask_size + j] = (1.0 / two_pi_sigma) * (-(x * x + y * y) / (2.0 * sigma * sigma)).exp();
            }
        }

        let sum: f32 = filter.iter().sum();
        for val in filter.iter_mut() {
            *val /= sum;
        }

        self.filter(&filter, mask_size, mask_size)
    }

    pub fn clear(&mut self, color: Pixel) {
        if let Some(_data) = self.data.as_mut() {
            for y in 0..self.height {
                for x in 0..self.width {
                    self.set_pixel_color(x, y, color.clone());
                }
            }
        }
    }

    pub fn draw_line(&mut self, x1: isize, y1: isize, x2: isize, y2: isize, color: Pixel) {
        let dx = (x2 - x1).abs();
        let dy = (y2 - y1).abs();

        if dx > dy {
            if x2 > x1 {
                for i in x1..=x2 {
                    let y = (((y2 - y1) as f32 / (x2 - x1) as f32) * (i - x1) as f32 + y1 as f32) as isize;
                    self.set_pixel_color(i as usize, y as usize, color.clone());
                }
            } else {
                for i in x2..=x1 {
                    let y = (((y1 - y2) as f32 / (x1 - x2) as f32) * (i - x2) as f32 + y2 as f32) as isize;
                    self.set_pixel_color(i as usize, y as usize, color.clone());
                }
            }
        } else {
            if y2 > y1 {
                for i in y1..=y2 {
                    let x = (((x2 - x1) as f32 / (y2 - y1) as f32) * (i - y1) as f32 + x1 as f32) as isize;
                    self.set_pixel_color(x as usize, i as usize, color.clone());
                }
            } else {
                for i in y2..=y1 {
                    let x = (((x1 - x2) as f32 / (y1 - y2) as f32) * (i - y2) as f32 + x2 as f32) as isize;
                    self.set_pixel_color(x as usize, i as usize, color.clone());
                }
            }
        }
    }

    // Following methods are helper methods to work with color

    fn get_pixel_gray(&self, x: usize, y: usize) -> u8 {
        let data = self.data.as_ref().unwrap();
        let index = (y * self.width + x) * 3;
        let r = data[index] as usize;
        let g = data[index + 1] as usize;
        let b = data[index + 2] as usize;
        (r + g + b) as u8 / 3
    }

    fn set_pixel_gray(&mut self, x: usize, y: usize, gray: u8) {
        let data = self.data.as_mut().unwrap();
        let index = (y * self.width + x) * 3;
        data[index] = gray;
        data[index + 1] = gray;
        data[index + 2] = gray;
    }

    fn get_pixel_color(&self, x: usize, y: usize) -> Pixel {
        let data = self.data.as_ref().unwrap();
        let index = (y * self.width + x) * 3;
        Pixel {
            r: data[index],
            g: data[index + 1],
            b: data[index + 2],
        }
    }

    fn set_pixel_color(&mut self, x: usize, y: usize, color: Pixel) {
        let data = self.data.as_mut().unwrap();
        let index = (y * self.width + x) * 3;
        data[index] = color.r;
        data[index + 1] = color.g;
        data[index + 2] = color.b;
    }
