struct Image {
    width: usize,
    height: usize,
    data: Vec<u8>,
}

impl Image {
    fn new() -> Image {
        Image {
            width: 0,
            height: 0,
            data: vec![],
        }
    }

    fn with_size(width: usize, height: usize) -> Image {
        Image {
            width,
            height,
            data: vec![0; 3 * width * height],
        }
    }

    fn from_image(src: &Image) -> Image {
        Image {
            width: src.width,
            height: src.height,
            data: src.data.clone(),
        }
    }

    fn init(&mut self, width: usize, height: usize) {
        self.width = width;
        self.height = height;
        self.data = vec![0; 3 * self.width * self.height];
    }

    fn get_mean_gray(&self) -> u8 {
        let sum: usize = (0..self.height)
            .flat_map(|i| (0..self.width).map(move |j| self.get_pixel_gray(j, i) as usize))
            .sum();
        (sum / (self.width * self.height)) as u8
    }

    fn binarize(&mut self, threshold: u8) {
        for i in 0..self.height {
            for j in 0..self.width {
                let c = self.get_pixel_gray(j, i);
                self.set_pixel_gray(j, i, if c > threshold { 255 } else { 0 });
            }
        }
    }

    fn flip_horizontal(&mut self) {
        let mut newdata = vec![0; 3 * self.width * self.height];
        for i in 0..self.height {
            for j in 0..self.width {
                let index1 = 3 * (i * self.width + j);
                let index2 = 3 * (i * self.width + self.width - j - 1);
                newdata[index1..index1 + 3].copy_from_slice(&self.data[index2..index2 + 3]);
            }
        }
        self.data = newdata;
    }

    fn flip_vertical(&mut self) {
        let mut newdata = vec![0; 3 * self.width * self.height];
        for i in 0..self.height {
            for j in 0..self.width {
                let index1 = 3 * (i * self.width + j);
                let index2 = 3 * ((self.height - i - 1) * self.width + j);
                newdata[index1..index1 + 3].copy_from_slice(&self.data[index2..index2 + 3]);
            }
        }
        self.data = newdata;
    }

    fn get_pixel_bilinear(&self, x: f32, y: f32) -> Pixel {
        let mut c = Pixel { r: 0, g: 0, b: 0 };
        if x < 0.0 || y < 0.0 || x > (self.width - 1) as f32 || y > (self.height - 1) as f32 {
            return c;
        }
        let x1 = x.floor() as usize;
        let y1 = y.floor() as usize;
        let dx = x - x1 as f32;
        let dy = y - y1 as f32;
        let c1 = self.get_pixel_color(x1, y1);
        let c2 = self.get_pixel_color(x1 + 1, y1);
        let c3 = self.get_pixel_color(x1, y1 + 1);
        let c4 = self.get_pixel_color(x1 + 1, y1 + 1);
        c.r = Image::round(Image::interpolate(c1.r as f32, c2.r as f32, c3.r as f32, c4.r as f32, dx, dy)) as u8;
        c.g = Image::round(Image::interpolate(c1.g as f32, c2.g as f32, c3.g as f32, c4.g as f32, dx, dy)) as u8;
        c.b = Image::round(Image::interpolate(c1.b as f32, c2.b as f32, c3.b as f32, c4.b as f32, dx, dy)) as u8;
        c
    }

    fn interpolate(x1: f32, x2: f32, x3: f32, x4: f32, dx: f32, dy: f32) -> f32 {
        let x5 = x2 * dx + x1 * (1.0 - dx);
        let x6 = x4 * dx + x3 * (1.0 - dx);
        x6 * dy + x5 * (1.0 - dy)
    }

    fn round(x: f32) -> f32 {
        if x - x.floor() < 0.5 {
            x.floor()
        } else {
            x.ceil()
        }
    }

    fn get_histogram_gray(&self) -> [usize; 256] {
        let mut histogram = [0; 256];
        for i in 0..self.height {
            for j in 0..self.width {
                histogram[self.get_pixel_gray(j, i) as usize] += 1;
            }
        }
        histogram
    }

    fn invert(&mut self) {
        for i in 0..self.data.len() {
            self.data[i] = 255 - self.data[i];
        }
    }

    fn crop(&self, posx: usize, posy: usize, width: usize, height: usize) -> Image {
        let mut resultimg = Image::with_size(width, height);
        for i in 0..height {
            for j in 0..width {
                let rgb = self.get_pixel_color(j + posx, i + posy);
                resultimg.set_pixel_color(j, i, rgb);
            }
        }
        resultimg
    }

    fn resize(&self, factor: usize) -> Image {
        let width = self.width / factor;
        let height = self.height / factor;
        let factor2 = factor * factor;

        let mut resultimg = Image::with_size(width, height);
        for i in 0..height {
            for j in 0..width {
                let minx = j * factor;
                let miny = i * factor;
                let maxx = minx + factor;
                let maxy = miny + factor;

                let mut sumr = 0;
                let mut sumg = 0;
                let mut sumb = 0;

                for i2 in miny..maxy {
                    for j2 in minx..maxx {
                        let rgb = self.get_pixel_color(j2, i2);
                        sumr += rgb.r as usize;
                        sumg += rgb.g as usize;
                        sumb += rgb.b as usize;
                    }
                }
                let rgb = Pixel {
                    r: (Image::round(sumr as f32 / factor2 as f32) as u8),
                    g: (Image::round(sumg as f32 / factor2 as f32) as u8),
                    b: (Image::round(sumb as f32 / factor2 as f32) as u8),
                };
                resultimg.set_pixel_color(j, i, rgb);
            }
        }
        resultimg
    }

    fn filter(&self, filter: &[f32], filterwidth: usize, filterheight: usize) -> Image {
        let mut ret = Image::with_size(self.width, self.height);
        let fox = filterwidth / 2;
        let foy = filterheight / 2;
        for i1 in 0..self.height {
            for j1 in 0..self.width {
                let mut sumr = 0.0;
                let mut sumg = 0.0;
                let mut sumb = 0.0;
                for i2 in -(foy as isize)..=(foy as isize) {
                    for j2 in -(fox as isize)..=(fox as isize) {
                        let x = max(0, min(self.width as isize - 1, j1 as isize + j2)) as usize;
                        let y = max(0, min(self.height as isize - 1, i1 as isize + i2)) as usize;
                        let offset3 = (i2 + foy as isize) as usize * filterwidth + (j2 + fox as isize) as usize;
                        let pixel = self.get_pixel_color(x, y);
                        sumr += pixel.r as f32 * filter[offset3];
                        sumg += pixel.g as f32 * filter[offset3];
                        sumb += pixel.b as f32 * filter[offset3];
                    }
                }
                let offset1 = (i1 * self.width + j1) * 3;
                ret.data[offset1] = Image::round(sumr) as u8;
                ret.data[offset1 + 1] = Image::round(sumg) as u8;
                ret.data[offset1 + 2] = Image::round(sumb) as u8;
            }
        }
        ret
    }

    fn gauss_blur(&self, sigma: f32, mut masksize: usize) -> Image {
        if masksize == 0 {
            masksize = (sigma.round() * 2.0 * 2.0 + 1.0) as usize;
        }
        let fsize = masksize * masksize;
        let fo = masksize / 2;
        let mut filter = vec![0.0; fsize];
        for i in -(fo as isize)..=(fo as isize) {
            for j in -(fo as isize)..=(fo as isize) {
                filter[((i + fo as isize) * masksize as isize + j + fo as isize) as usize] =
                    (1.0 / (2.0 * PI * sigma)) * f32::exp(-((i * i + j * j) as f32) / (2.0 * sigma * sigma));
            }
        }

        let sum: f32 = filter.iter().sum();
        for f in &mut filter {
            *f /= sum;
        }

        self.filter(&filter, masksize, masksize)
    }

    fn clear(&mut self, color: Pixel) {
        for y in 0..self.height {
            for x in 0..self.width {
                self.set_pixel_color(x, y, color);
            }
        }
    }

    fn draw_line(&mut self, x1: isize, y1: isize, x2: isize, y2: isize, color: Pixel) {
        let dx = (x2 - x1).abs();
        let dy = (y2 - y1).abs();
        if dx > dy {
            if x2 > x1 {
                for i in x1..=x2 {
                    let y = ((y2 as f32 - y1 as f32) / (x2 as f32 - x1 as f32) * (i as f32 - x1 as f32) + y1 as f32)
