                        .round() as isize;
                    self.set_pixel_color(i as usize, y as usize, color);
                }
            }
        } else {
            if y2 > y1 {
                for i in y1..=y2 {
                    let x = ((x2 as f32 - x1 as f32) / (y2 as f32 - y1 as f32) * (i as f32 - y1 as f32) + x1 as f32)
                        .round() as isize;
