use std::fs::File;
use std::io::{Read, Write, Seek, SeekFrom};
use std::str;

const IMGTYPE_BMP: i32 = 0;
const IMGTYPE_PPM: i32 = 1;
const IMGTYPE_PGM: i32 = 2;
const IMGTYPE_RAW: i32 = 3;
const IMGTYPE_UNSUPPORTED: i32 = -1;

pub struct Image {
    pub width: i32,
    pub height: i32,
    pub data: Option<Vec<u8>>,
}

impl Image {
    pub fn set_pixel_gray(&mut self, x: i32, y: i32, value: u8) {
        let index = (self.height - y - 1) * self.width + x;
        if let Some(ref mut data) = self.data {
            data[index as usize] = value;
        }
    }

    pub fn set_pixel_color(&mut self, x: i32, y: i32, rgb: Pixel) {
        let index = (self.height - y - 1) * self.width * 3 + x * 3;
        if let Some(ref mut data) = self.data {
            data[index as usize] = rgb.r;
            data[index as usize + 1] = rgb.g;
            data[index as usize + 2] = rgb.b;
        }
    }

    pub fn get_pixel_color(&self, x: i32, y: i32) -> Pixel {
        let index = y * self.width * 3 + x * 3;
        if let Some(ref data) = self.data {
            Pixel {
                r: data[index as usize],
                g: data[index as usize + 1],
                b: data[index as usize + 2],
            }
        } else {
            Pixel { r: 0, g: 0, b: 0 }
        }
    }

    pub fn get_pixel_gray(&self, x: i32, y: i32) -> u8 {
        let index = y * self.width + x;
        if let Some(ref data) = self.data {
            data[index as usize]
        } else {
            0
        }
    }
}

pub struct Pixel {
    r: u8,
    g: u8,
    b: u8,
}

pub struct ImageIO;

impl ImageIO {
    pub fn get_file_extension(filename: &str) -> &str {
        let filename = filename.rsplit(&['/', '\\'][..]).next().unwrap_or(filename);
        if let Some(extension) = filename.rsplit('.').next() {
            extension
        } else {
            ""
        }
    }

    pub fn get_image_type(filename: &str) -> i32 {
        let extension = Self::get_file_extension(filename);
        match extension.to_lowercase().as_str() {
            "bmp" => IMGTYPE_BMP,
            "ppm" => IMGTYPE_PPM,
            "pgm" => IMGTYPE_PGM,
            "raw" => IMGTYPE_RAW,
            _ => IMGTYPE_UNSUPPORTED,
        }
    }

    pub fn load_image(filename: &str, image: &mut Image) {
        let img_type = Self::get_image_type(filename);
        if img_type == IMGTYPE_UNSUPPORTED {
            println!("Error loading image {}, unsupported image type!", filename);
        } else {
            Self::load_image_with_type(filename, image, img_type);
        }
    }

    pub fn load_image_with_type(filename: &str, image: &mut Image, image_type: i32) {
        match image_type {
            IMGTYPE_BMP => Self::load_image_bmp(filename, image),
            IMGTYPE_PPM => Self::load_image_ppm(filename, image),
            IMGTYPE_PGM => Self::load_image_pgm(filename, image),
            IMGTYPE_RAW => Self::load_image_raw(filename, image, 0, 0),
            _ => {}
        }
    }

    fn load_image_bmp(filename: &str, image: &mut Image) {
        let mut file = match File::open(filename) {
            Ok(file) => file,
            Err(_) => {
                println!("Error opening {}!", filename);
                return;
            }
        };

        let mut header = [0u8; 2];
        if file.read(&mut header).is_err() || !(header[0] == b'B' && header[1] == b'M') {
            println!("Error loading image {}, wrong file format!", filename);
            return;
        }

        file.seek(SeekFrom::Start(10)).unwrap();
        let mut bm_offset = [0u8; 4];
        file.read(&mut bm_offset).unwrap();
        let bm_offset = i32::from_le_bytes(bm_offset) as u64;

        file.seek(SeekFrom::Start(18)).unwrap();
        let mut dimensions = [0u8; 8];
        file.read(&mut dimensions).unwrap();
        image.width = i32::from_le_bytes(dimensions[0..4].try_into().unwrap());
        image.height = i32::from_le_bytes(dimensions[4..8].try_into().unwrap());

        file.seek(SeekFrom::Start(28)).unwrap();
        let mut bpp = [0u8; 2];
        file.read(&mut bpp).unwrap();
        let bpp = i16::from_le_bytes(bpp);
        if !(bpp == 8 || bpp == 24) {
            println!(
                "Error loading image {}, can only load BMP files with 8 or 24 bpp!",
                filename
            );
            return;
        }

        let mut compression = [0u8; 4];
        file.read(&mut compression).unwrap();
        if i32::from_le_bytes(compression) != 0 {
            println!(
                "Error loading image {}, can only load uncompressed BMP files!",
                filename
            );
            return;
        }

        if image.data.is_some() {
            image.data = None;
        }
        image.data = Some(vec![0u8; (image.height * image.width * 3) as usize]);

        match bpp {
            8 => {
                let tmp = image.width % 4;
                let bpr = if tmp == 0 { image.width } else { image.width + 4 - tmp };
                let bm_size = bpr * image.height;

                let mut buffer = vec![0u8; bm_size as usize];
                file.seek(SeekFrom::Start(bm_offset)).unwrap();
                file.read(&mut buffer).unwrap();

                let mut pos = 0;
                for i in 0..image.height {
                    for j in 0..image.width {
                        if let Some(ref mut data) = image.data {
                            data[((image.height - i - 1) * image.width + j) as usize] = buffer[pos];
                        }
                        pos += 1;
                    }
                    pos += (4 - tmp) as usize;
                }
            },
            24 => {
                let tmp = (image.width * 3) % 4;
                let bpr = if tmp == 0 {
                    image.width * 3
                } else {
                    image.width * 3 + 4 - tmp
                };
                let bm_size = bpr * image.height;
                let mut buffer = vec![0u8; bm_size as usize];
                file.seek(SeekFrom::Start(bm_offset)).unwrap();
                file.read(&mut buffer).unwrap();

                let mut pos = 0;
                for i in 0..image.height {
                    for j in 0..image.width {
                        let rgb = Pixel {
                            b: buffer[pos],
                            g: buffer[pos + 1],
                            r: buffer[pos + 2],
                        };
                        image.set_pixel_color(j, image.height - i - 1, rgb);
                        pos += 3;
                    }
                    pos += (4 - tmp) as usize;
                }
            },
            _ => {}
        }
    }

    fn load_image_ppm(filename: &str, image: &mut Image) {
        let mut file = match File::open(filename) {
            Ok(file) => file,
            Err(_) => {
                println!("Error opening {}!", filename);
                return;
            }
        };

        let filesize = file.metadata().unwrap().len() as usize;
        let mut buffer = vec![0u8; filesize];
        file.read(&mut buffer).unwrap();

        let header = str::from_utf8(&buffer).unwrap();
        let mut parts = header.split_whitespace();
        let magic = parts.next().unwrap_or_default();

        if magic != "P6" {
            println!("Error loading image {}, wrong file format!", filename);
            return;
        }

        let width = parts.next().unwrap_or("0").parse::<i32>().unwrap_or(0);
        let height = parts.next().unwrap_or("0").parse::<i32>().unwrap_or(0);
        let max_colors = parts.next().unwrap_or("0").parse::<i32>().unwrap_or(0);

        if max_colors != 255 {
            println!("Error loading image {}, wrong file format!", filename);
            return;
        }

        image.width = width;
        image.height = height;

        if image.data.is_some() {
            image.data = None;
        }
        image.data = Some(vec![0u8; (image.height * image.width * 3) as usize]);

        let data_start = header.lines().take(4).fold(0, |acc, line| acc + line.len() + 1);
        let mut pos = data_start;

        for i in 0..height {
            for j in 0..width {
                let r = buffer[pos];
                let g = buffer[pos + 1];
                let b = buffer[pos + 2];
                pos += 3;

                image.set_pixel_color(j, i, Pixel { r, g, b });
            }
        }
    }

    fn load_image_pgm(filename: &str, image: &mut Image) {
        let mut file = match File::open(filename) {
            Ok(file) => file,
            Err(_) => {
                println!("Error opening {}!", filename);
                return;
            }
        };

        let filesize = file.metadata().unwrap().len() as usize;
