        let header = str::from_utf8(&buffer).unwrap();
        let mut parts = header.split_whitespace();
        let magic = parts.next().unwrap_or_default();

        if magic != "P5" {
            println!("Error loading image {}, wrong file format!", filename);
            return;
        }

        let width = parts.next().unwrap_or("0").parse::<i32>().unwrap_or(0);
        let height = parts.next().unwrap_or("0").parse::<i32>().unwrap_or(0);
        let max_colors = parts.next().unwrap_or("0").parse::<i32>().unwrap_or(0);

        if max_colors != 255 {
            println!("Error loading image {}, wrong file format!", filename);
            return;
        }

        image.width = width;
        image.height = height;

        if image.data.is_some() {
            image.data = None;
        }
        image.data = Some(vec![0u8; (image.height * image.width) as usize]);

        let data_start = header.lines().take(4).fold(0, |acc, line| acc + line.len() + 1);
        let mut pos = data_start;

        for i in 0..height {
            for j in 0..width {
                image.set_pixel_gray(j, i, buffer[pos]);
                pos += 1;
            }
        }
    }

    fn load_image_raw(filename: &str, image: &mut Image, width: i32, height: i32) {
        let mut file = match File::open(filename) {
            Ok(file) => file,
            Err(_) => {
                println!("Error opening {}!", filename);
                return;
            }
        };

        let filesize = file.metadata().unwrap().len() as usize;
        let mut width = width;
        let mut height = height;

        if width == 0 || height == 0 {
            width = (filesize as f64).sqrt() as i32;
            height = width;
            if (height * width) as usize != filesize {
                println!("Error loading image {}, wrong file format!", filename);
                return;
            }
        }

        image.width = width;
        image.height = height;
        if image.data.is_some() {
            image.data = None;
        }
        image.data = Some(vec![0u8; (image.height * image.width) as usize]);

        let mut buffer = vec![0u8; filesize];
        file.read(&mut buffer).unwrap();

        let mut pos = 0;
        for i in 0..height {
            for j in 0..width {
                image.set_pixel_gray(j, i, buffer[pos]);
                pos += 1;
            }
        }
    }

    pub fn save_image(filename: &str, image: &Image) {
        let img_type = Self::get_image_type(filename);
        if img_type == IMGTYPE_UNSUPPORTED {
            println!("Error saving image to {}, unknown image format!", filename);
        } else {
            Self::save_image_with_type(filename, image, img_type);
        }
    }

    pub fn save_image_with_type(filename: &str, image: &Image, image_type: i32) {
        match image_type {
            IMGTYPE_BMP => Self::save_image_bmp(filename, image),
            IMGTYPE_PPM => Self::save_image_ppm(filename, image),
            IMGTYPE_PGM => Self::save_image_pgm(filename, image),
            IMGTYPE_RAW => Self::save_image_raw(filename, image),
            _ => {}
        }
    }

    fn save_image_bmp(filename: &str, image: &Image) {
        let mut file = match File::create(filename) {
            Ok(file) => file,
            Err(_) => {
                println!("Error opening {}!", filename);
                return;
            }
        };

        let header = [b'B', b'M'];
        file.write(&header).unwrap();

        let row_size = (image.width * 3 + 3) & !3;
        let data_size = (row_size * image.height) as u32;
        let file_size = 54 + data_size;
        file.write(&file_size.to_le_bytes()).unwrap();

        let reserved = 0u32;
        file.write(&reserved.to_le_bytes()).unwrap();

        let data_offset = 54u32;
        file.write(&data_offset.to_le_bytes()).unwrap();

        let header_size = 40u32;
        file.write(&header_size.to_le_bytes()).unwrap();

        file.write(&(image.width as u32).to_le_bytes()).unwrap();
        file.write(&(image.height as u32).to_le_bytes()).unwrap();

        let planes = 1u16;
        file.write(&planes.to_le_bytes()).unwrap();

        let bits_per_pixel = 24u16;
        file.write(&bits_per_pixel.to_le_bytes()).unwrap();

        let compression = 0u32;
        file.write(&compression.to_le_bytes()).unwrap();

        file.write(&data_size.to_le_bytes()).unwrap();

        let ppm = 0u32;
        file.write(&ppm.to_le_bytes()).unwrap(); // Horizontal resolution
        file.write(&ppm.to_le_bytes()).unwrap(); // Vertical resolution

        let color_table = 0u32;
        file.write(&color_table.to_le_bytes()).unwrap(); // Colors in color table
        file.write(&color_table.to_le_bytes()).unwrap(); // Important color count

        let mut row = vec![0u8; row_size as usize];
        if let Some(ref data) = image.data {
            for i in 0..image.height {
                let offset = ((image.height - i - 1) * image.width * 3) as usize;
                for j in 0..(image.width * 3) {
                    row[j as usize] = data[offset + j as usize];
                }
                file.write(&row).unwrap();
            }
        }
    }

    fn save_image_ppm(filename: &str, image: &Image) {
        let mut file = match File::create(filename) {
            Ok(file) => file,
            Err(_) => {
                println!("Error opening {}!", filename);
                return;
            }
        };

        writeln!(file, "P6\n{} {}\n255", image.width, image.height).unwrap();

        if let Some(ref data) = image.data {
            file.write(&data).unwrap();
        }
    }

    fn save_image_pgm(filename: &str, image: &Image) {
        let mut file = match File::create(filename) {
            Ok(file) => file,
            Err(_) => {
                println!("Error opening {}!", filename);
                return;
            }
        };

        writeln!(file, "P5\n{} {}\n255", image.width, image.height).unwrap();

        if let Some(ref data) = image.data {
            for (i, pixel) in data.chunks(3).enumerate() {
                file.write(&[pixel[0]]).unwrap();
            }
        }
    }

    fn save_image_raw(filename: &str, image: &Image) {
        let mut file = match File::create(filename) {
            Ok(file) => file,
            Err(_) => {
                println!("Error opening {}!", filename);
                return;
            }
        };

        if let Some(ref data) = image.data {
            for (i, pixel) in data.chunks(3).enumerate() {
                file.write(&[pixel[0]]).unwrap();
            }
        }
    }
}

