use std::fs::File;
use std::io::{self, Read, Write, Seek, SeekFrom};
use std::path::Path;
use std::str;
use std::ffi::CStr;

const IMGTYPE_BMP: i32 = 0;
const IMGTYPE_PPM: i32 = 1;
const IMGTYPE_PGM: i32 = 2;
const IMGTYPE_RAW: i32 = 3;
const IMGTYPE_UNSUPPORTED: i32 = -1;

#[derive(Default)]
struct Image {
    width: i32,
    height: i32,
    data: Vec<u8>,
}

impl Image {
    fn set_pixel_gray(&mut self, x: i32, y: i32, value: u8) {
        let index = (y * self.width + x) as usize * 3;
        self.data[index..index + 3].fill(value);
    }

    fn set_pixel_color(&mut self, x: i32, y: i32, pixel: Pixel) {
        let index = (y * self.width + x) as usize * 3;
        self.data[index] = pixel.r;
        self.data[index + 1] = pixel.g;
        self.data[index + 2] = pixel.b;
    }

    fn get_pixel_color(&self, x: i32, y: i32) -> Pixel {
        let index = (y * self.width + x) as usize * 3;
        Pixel {
            r: self.data[index],
            g: self.data[index + 1],
            b: self.data[index + 2],
        }
    }

    fn get_pixel_gray(&self, x: i32, y: i32) -> u8 {
        self.data[(y * self.width + x) as usize * 3]
    }
}

struct Pixel {
    r: u8,
    g: u8,
    b: u8,
}

struct ImageIO;

impl ImageIO {
    fn get_file_extension(filename: &str) -> &str {
        Path::new(filename)
            .extension()
            .unwrap_or_default()
            .to_str()
            .unwrap_or_default()
    }

    fn get_image_type(filename: &str) -> i32 {
        match Self::get_file_extension(filename).to_lowercase().as_str() {
            "bmp" => IMGTYPE_BMP,
            "ppm" => IMGTYPE_PPM,
            "pgm" => IMGTYPE_PGM,
            "raw" => IMGTYPE_RAW,
            _ => IMGTYPE_UNSUPPORTED,
        }
    }

    fn load_image(&self, filename: &str, image: &mut Image) -> io::Result<()> {
        let img_type = Self::get_image_type(filename);
        if img_type == IMGTYPE_UNSUPPORTED {
            println!("Error loading image {}, unsupported image type!", filename);
            return Ok(());
        }
        self.load_image_with_type(filename, image, img_type)
    }

    fn load_image_with_type(&self, filename: &str, image: &mut Image, image_type: i32) -> io::Result<()> {
        match image_type {
            IMGTYPE_BMP => self.load_image_bmp(filename, image),
            IMGTYPE_PPM => self.load_image_ppm(filename, image),
            IMGTYPE_PGM => self.load_image_pgm(filename, image),
            IMGTYPE_RAW => self.load_image_raw(filename, image, 0, 0),
            _ => Err(io::Error::new(io::ErrorKind::InvalidInput, "Unsupported image type")),
        }
    }

    fn open_file(filename: &str, mode: &str) -> io::Result<File> {
        match mode {
            "rb" => File::open(filename),
            "wb" => File::create(filename),
            _ => Err(io::Error::new(io::ErrorKind::InvalidInput, "Invalid mode")),
        }
    }

    fn read_u8(file: &mut File) -> io::Result<u8> {
        let mut buf = [0u8; 1];
        file.read_exact(&mut buf)?;
        Ok(buf[0])
    }

    fn read_u16(file: &mut File) -> io::Result<u16> {
        let mut buf = [0u8; 2];
        file.read_exact(&mut buf)?;
        Ok(u16::from_le_bytes(buf))
    }

    fn read_u32(file: &mut File) -> io::Result<u32> {
        let mut buf = [0u8; 4];
        file.read_exact(&mut buf)?;
        Ok(u32::from_le_bytes(buf))
    }

    fn load_image_bmp(&self, filename: &str, image: &mut Image) -> io::Result<()> {
        let mut fp = Self::open_file(filename, "rb")?;
        let mut header = [0u8; 2];
        fp.read_exact(&mut header)?;

        if header != [b'B', b'M'] {
            println!("Error loading image {}, wrong file format!", filename);
            return Ok(());
        }

        fp.seek(SeekFrom::Start(10))?;
        let bm_offset = Self::read_u32(&mut fp)? as u64;

        fp.seek(SeekFrom::Start(18))?;
        image.width = Self::read_u32(&mut fp)? as i32;
        image.height = Self::read_u32(&mut fp)? as i32;

        fp.seek(SeekFrom::Start(28))?;
        let bpp = Self::read_u16(&mut fp)?;
        if bpp != 8 && bpp != 24 {
            println!("Error loading image {}, can only load BMP files with 8 or 24 bpp!", filename);
            return Ok(());
        }

        let compression = Self::read_u32(&mut fp)?;
        if compression != 0 {
            println!("Error loading image {}, can only load uncompressed BMP files!", filename);
            return Ok(());
        }

        image.data = vec![0; (image.height * image.width * 3) as usize];

        if bpp == 8 {
            let bpr = ((image.width + 3) / 4) * 4;
            let bm_size = (bpr * image.height) as usize;
            let mut buffer = vec![0; bm_size];
            fp.seek(SeekFrom::Start(bm_offset))?;
            fp.read_exact(&mut buffer)?;

            let mut pos = 0;
            for i in 0..image.height {
                for j in 0..image.width {
                    image.set_pixel_gray(j, image.height - i - 1, buffer[pos]);
                    pos += 1;
                }
                pos += (bpr - image.width) as usize;
            }
        } else if bpp == 24 {
            let bpr = (((image.width * 3) + 3) / 4) * 4;
            let bm_size = (bpr * image.height) as usize;
            let mut buffer = vec![0; bm_size];
            fp.seek(SeekFrom::Start(bm_offset))?;
            fp.read_exact(&mut buffer)?;

            let mut pos = 0;
            for i in 0..image.height {
                for j in 0..image.width {
                    let pixel = Pixel { b: buffer[pos], g: buffer[pos + 1], r: buffer[pos + 2] };
                    image.set_pixel_color(j, image.height - i - 1, pixel);
                    pos += 3;
                }
                pos += (bpr - image.width * 3) as usize;
            }
        }
        Ok(())
    }

    fn load_image_ppm(&self, filename: &str, image: &mut Image) -> io::Result<()> {
        let mut fp = Self::open_file(filename, "rb")?;
        let filesize = fp.seek(SeekFrom::End(0))? as usize;
        fp.seek(SeekFrom::Start(0))?;

        let mut buffer = vec![0; filesize];
        fp.read_exact(&mut buffer)?;

        let (id, sizex, sizey, levels) = unsafe {
            let c_str = CStr::from_bytes_with_nul_unchecked(&buffer);
            let str_data = c_str.to_str().unwrap_or("");
            let mut parts = str_data.split_whitespace();
            let id = parts.next().unwrap_or("");
            let sizex = parts.next().unwrap_or("0").parse::<i32>().unwrap_or(0);
            let sizey = parts.next().unwrap_or("0").parse::<i32>().unwrap_or(0);
            let levels = parts.next().unwrap_or("0").parse::<i32>().unwrap_or(0);
            (id, sizex, sizey, levels)
        };

        if id != "P6" || levels != 255 {
            println!("Error loading image {}, wrong file format!", filename);
            return Ok(());
        }

        image.width = sizex;
        image.height = sizey;
        image.data = vec![0; (image.height * image.width * 3) as usize];

        let pos = filesize - (sizex * sizey * 3) as usize;
        let pixel_data = &buffer[pos..];
        image.data.copy_from_slice(pixel_data);

        Ok(())
    }

    fn load_image_pgm(&self, filename: &str, image: &mut Image) -> io::Result<()> {
        let mut fp = Self::open_file(filename, "rb")?;
        let filesize = fp.seek(SeekFrom::End(0))? as usize;
        fp.seek(SeekFrom::Start(0))?;

        let mut buffer = vec![0; filesize];
        fp.read_exact(&mut buffer)?;

        let (id, sizex, sizey, levels) = unsafe {
            let c_str = CStr::from_bytes_with_nul_unchecked(&buffer);
            let str_data = c_str.to_str().unwrap_or("");
            let mut parts = str_data.split_whitespace();
            let id = parts.next().unwrap_or("");
            let sizex = parts.next().unwrap_or("0").parse::<i32>().unwrap_or(0);
            let sizey = parts.next().unwrap_or("0").parse::<i32>().unwrap_or(0);
            let levels = parts.next().unwrap_or("0").parse::<i32>().unwrap_or(0);
            (id, sizex, sizey, levels)
        };

        if id != "P5" || levels != 255 {
            println!("Error loading image {}, wrong file format!", filename);
            return Ok(());
        }

        image.width = sizex;
        image.height = sizey;
        image.data = vec![0; (image.height * image.width * 3) as usize];

        let pos = filesize - (sizex * sizey) as usize;
        let pixel_data = &buffer[pos..];

        let mut index = 0;
        for &gray_value in pixel_data {
            image.set_pixel_gray(index % sizex, index / sizex, gray_value);
            index += 1;
        }

        Ok(())
    }

    fn save_image(&self, filename: &str, image: &Image) -> io::Result<()> {
        let img_type = Self::get_image_type(filename);
        if img_type == IMGTYPE_UNSUPPORTED {
            println!("Error saving image to {}, unknown image format!", filename);
            return Ok(());
        }
        self.save_image_with_type(filename, image, img_type)
    }

    fn save_image_with_type(&self, filename: &str, image: &Image, image_type: i32) -> io::Result<()> {
        match image_type {
            IMGTYPE_BMP => self.save_image_bmp(filename, image),
            IMGTYPE_PPM => self.save_image_ppm(filename, image),
            IMGTYPE_PGM => self.save_image_pgm(filename, image),
            _ => Err(io::Error::new(io::ErrorKind::InvalidInput, "Unsupported image type")),
        }
    }

    fn save_image_bmp(&self, filename: &str, image: &Image) -> io::Result<()> {
        let mut fp = Self::open_file(filename, "wb")?;
        let header = [b'B', b'M'];
        fp.write_all(&header)?;

        let row_size = ((image.width * 3 + 3) / 4) * 4;
        let file_size = 54 + row_size * image.height;

        fp.write_all(&(file_size as u32).to_le_bytes())?;
        fp.write_all(&[0u8; 4])?; // Reserved
        fp.write_all(&54u32.to_le_bytes())?; // Offset
        fp.write_all(&40u32.to_le_bytes())?; // Info header size
        fp.write_all(&(image.width as u32).to_le_bytes())?;
        fp.write_all(&(image.height as u32).to_le_bytes())?;
        fp.write_all(&1u16.to_le_bytes())?; // Planes
        fp.write_all(&24u16.to_le_bytes())?; // Bit count
        fp.write_all(&[0u8; 24])?; // Other header data

        let mut row = vec![0u8; row_size as usize];
        for i in 0..image.height {
            let line_start = (3 * image.width * (image.height - i - 1)) as usize;
            row[..(3 * image.width) as usize].copy_from_slice(&image.data[line_start..line_start + 3 * image.width as usize]);
            fp.write_all(&row)?;
        }

        Ok(())
    }

    fn save_image_ppm(&self, filename: &str, image: &Image) -> io::Result<()> {
        let mut fp = Self::open_file(filename, "wb")?;
        writeln!(fp, "P6\n{} {}\n255", image.width, image.height)?;

        let buffer = &image.data;
        fp.write_all(buffer)?;

        Ok(())
    }

    fn save_image_pgm(&self, filename: &str, image: &Image) -> io::Result<()> {
        let mut fp = Self::open_file(filename, "wb")?;
        writeln!(fp, "P5\n{} {}\n255", image.width, image.height)?;

        for y in 0..image.height {
            for x in 0..image.width {
                fp.write_all(&[image.get_pixel_gray(x, y)])?;
            }
        }

        Ok(())
    }

    fn load_image_raw(&self, filename: &str, image: &mut Image, width: i32, height: i32) -> io::Result<()> {
        let mut fp = Self::open_file(filename, "rb")?;
        let mut image_width = width;
        let mut image_height = height;

        if image_width == 0 || image_height == 0 {
            fp.seek(SeekFrom::End(0))?;
            let file_size = fp.seek(SeekFrom::Start(0))?;
            let calculated_dim = (file_size as f64).sqrt() as i32;
            if calculated_dim * calculated_dim != file_size as i32 {
                println!("Error loading image {}, wrong file format!", filename);
                return Ok(());
            }
            image_width = calculated_dim;
            image_height = calculated_dim;
        }

        image.width = image_width;
        image.height = image_height;
        image.data = vec![0u8; (image.width * image.height * 3) as usize];

        let mut buffer = vec![0; (image.width * image.height) as usize];
        fp.read_exact(&mut buffer)?;

        buffer.iter().enumerate().for_each(|(index, &c)| {
            image.set_pixel_gray(index as i32 % image_width, index as i32 / image_width, c);
        });

        Ok(())
    }

    fn save_image_raw(&self, filename: &str, image: &Image) -> io::Result<()> {
        let mut fp = Self::open_file(filename, "wb")?;

        for y in 0..image.height {
            for x in 0..image.width {
                let c = image.get_pixel_gray(x, y);
                fp.write_all(&[c])?;
            }
        }

        Ok(())
    }
}

