use std::fs::File;
use std::io::{Read, Write, Seek, SeekFrom};
use std::path::Path;
use std::ffi::OsStr;

const IMGTYPE_BMP: i32 = 0;
const IMGTYPE_PPM: i32 = 1;
const IMGTYPE_PGM: i32 = 2;
const IMGTYPE_RAW: i32 = 3;
const IMGTYPE_UNSUPPORTED: i32 = -1;

#[derive(Clone)]
pub struct Pixel {
    pub R: u8,
    pub G: u8,
    pub B: u8,
}

pub struct Image {
    pub width: i32,
    pub height: i32,
    pub data: Option<Vec<u8>>,
}

impl Image {
    pub fn set_pixel_gray(&mut self, x: i32, y: i32, value: u8) {
        let index = (y * self.width + x) as usize * 3;
        if let Some(data) = self.data.as_mut() {
            data[index] = value;
            data[index + 1] = value;
            data[index + 2] = value;
        }
    }

    pub fn set_pixel_color(&mut self, x: i32, y: i32, rgb: Pixel) {
        let index = (y * self.width + x) as usize * 3;
        if let Some(data) = self.data.as_mut() {
            data[index] = rgb.R;
            data[index + 1] = rgb.G;
            data[index + 2] = rgb.B;
        }
    }

    pub fn get_pixel_color(&self, x: i32, y: i32) -> Pixel {
        let index = (y * self.width + x) as usize * 3;
        if let Some(data) = &self.data {
            Pixel {
                R: data[index],
                G: data[index + 1],
                B: data[index + 2],
            }
        } else {
            Pixel { R: 0, G: 0, B: 0 }
        }
    }

    pub fn get_pixel_gray(&self, x: i32, y: i32) -> u8 {
        let index = (y * self.width + x) as usize * 3;
        if let Some(data) = &self.data {
            data[index]
        } else {
            0
        }
    }
}

pub struct ImageIO;

impl ImageIO {
    pub fn get_file_extension(filename: &str) -> &str {
        if let Some(extension) = Path::new(filename)
            .extension()
            .and_then(OsStr::to_str)
        {
            extension
        } else {
            ""
        }
    }

    pub fn get_image_type(filename: &str) -> i32 {
        let extension = Self::get_file_extension(filename);
        match extension.to_lowercase().as_str() {
            "bmp" => IMGTYPE_BMP,
            "ppm" => IMGTYPE_PPM,
            "pgm" => IMGTYPE_PGM,
            "raw" => IMGTYPE_RAW,
            _ => IMGTYPE_UNSUPPORTED,
        }
    }

    pub fn load_image(filename: &str, image: &mut Image) {
        let img_type = Self::get_image_type(filename);
        if img_type == IMGTYPE_UNSUPPORTED {
            eprintln!("Error loading image {}, unsupported image type!", filename);
            return;
        }
        Self::load_image_with_type(filename, image, img_type);
    }

    fn load_image_with_type(filename: &str, image: &mut Image, image_type: i32) {
        match image_type {
            IMGTYPE_BMP => Self::load_image_bmp(filename, image),
            IMGTYPE_PPM => Self::load_image_ppm(filename, image),
            IMGTYPE_PGM => Self::load_image_pgm(filename, image),
            IMGTYPE_RAW => Self::load_image_raw(filename, image, 0, 0),
            _ => {}
        }
    }

    fn load_image_bmp(filename: &str, image: &mut Image) {
        let mut file = match File::open(filename) {
            Ok(file) => file,
            Err(_) => {
                eprintln!("Error opening {}!", filename);
                return;
            }
        };

        let mut header = [0; 2];
        if file.read_exact(&mut header).is_err() || header != [b'B', b'M'] {
            eprintln!("Error loading image {}, wrong file format!", filename);
            return;
        }

        let mut bm_offset = [0; 4];
        file.seek(SeekFrom::Start(10)).unwrap();
        file.read_exact(&mut bm_offset).unwrap();
        let bm_offset = i32::from_le_bytes(bm_offset) as u64;

        file.seek(SeekFrom::Start(18)).unwrap();
        let mut dimensions = [0; 4];
        file.read_exact(&mut dimensions).unwrap();
        image.width = i32::from_le_bytes(dimensions);
        file.read_exact(&mut dimensions).unwrap();
        image.height = i32::from_le_bytes(dimensions);

        file.seek(SeekFrom::Start(28)).unwrap();
        let mut bpp = [0; 2];
        file.read_exact(&mut bpp).unwrap();
        let bpp = i16::from_le_bytes(bpp);
        if bpp != 8 && bpp != 24 {
            eprintln!("Error loading image {}, can only load BMP files with 8 or 24 bpp!", filename);
            return;
        }

        let mut compression = [0; 4];
        file.read_exact(&mut compression).unwrap();
        let compression = i32::from_le_bytes(compression);
        if compression != 0 {
            eprintln!("Error loading image {}, can only load uncompressed BMP files!", filename);
            return;
        }

        let image_size = (image.height * image.width * 3) as usize;
        image.data = Some(vec![0; image_size]);

        if bpp == 8 {
            // Loading 8bpp images
            Self::load_image_bmp_8bpp(&mut file, image, bm_offset);
        } else if bpp == 24 {
            // Loading 24bpp images
            Self::load_image_bmp_24bpp(&mut file, image, bm_offset);
        }
    }

    fn load_image_bmp_8bpp(file: &mut File, image: &mut Image, bm_offset: u64) {
        let pad_size = (4 - (image.width % 4)) % 4;
        let row_size = (image.width + pad_size) as usize;
        let mut buffer = vec![0u8; row_size * image.height as usize];

        file.seek(SeekFrom::Start(bm_offset)).unwrap();
        file.read_exact(&mut buffer).unwrap();

        if let Some(data) = image.data.as_mut() {
            for i in 0..image.height {
                let buf_idx = (i * row_size as i32) as usize;
                for j in 0..image.width {
                    let buf_pos = buf_idx + j as usize;
                    data[(i * image.width + j) as usize] = buffer[buf_pos];
                }
            }
        }
    }

    fn load_image_bmp_24bpp(file: &mut File, image: &mut Image, bm_offset: u64) {
        let pad_size = (4 - ((image.width * 3) % 4)) % 4;
        let row_size = (image.width * 3 + pad_size) as usize;
        let mut buffer = vec![0u8; row_size * image.height as usize];

        file.seek(SeekFrom::Start(bm_offset)).unwrap();
        file.read_exact(&mut buffer).unwrap();

        if let Some(data) = image.data.as_mut() {
            for i in 0..image.height {
                let buf_idx = (i * row_size as i32) as usize;
                for j in 0..image.width {
                    let buf_pos = buf_idx + (j as usize * 3);
                    let pixel = [
                        buffer[buf_pos],
                        buffer[buf_pos + 1],
                        buffer[buf_pos + 2],
                    ];
                    data[(i * image.width + j) as usize * 3..(i * image.width + j + 1) as usize * 3].copy_from_slice(&pixel);
                }
            }
        }
    }

    fn load_image_ppm(filename: &str, image: &mut Image) {
        let mut file = match File::open(filename) {
            Ok(file) => file,
            Err(_) => {
                eprintln!("Error opening {}!", filename);
                return;
            }
        };

        let mut buffer = Vec::new();
        file.read_to_end(&mut buffer).unwrap();

        let header = str::from_utf8(&buffer[..]).unwrap();
        if !header.starts_with("P6") || !header.contains("255") {
            eprintln!("Error loading image {}, wrong file format!", filename);
            return;
        }

        let mut iter = header.split_whitespace();
        iter.next(); // Skip "P6"
        let sizex: i32 = iter.next().unwrap().parse().unwrap();
        let sizey: i32 = iter.next().unwrap().parse().unwrap();
        iter.next(); // Skip "255"

        image.width = sizex;
        image.height = sizey;

        let data_begin = header.len() - sizex as usize * sizey as usize * 3;
        let data = &buffer[data_begin..];

        image.data = Some(data.to_vec());
    }

    fn load_image_pgm(filename: &str, image: &mut Image) {
        let mut file = match File::open(filename) {
            Ok(file) => file,
            Err(_) => {
                eprintln!("Error opening {}!", filename);
                return;
            }
        };

        let mut buffer = Vec::new();
        file.read_to_end(&mut buffer).unwrap();

        let header = str::from_utf8(&buffer[..]).unwrap();
        if !header.starts_with("P5") || !header.contains("255") {
            eprintln!("Error loading image {}, wrong file format!", filename);
            return;
        }

        let mut iter = header.split_whitespace();
        iter.next(); // Skip "P5"
        let sizex: i32 = iter.next().unwrap().parse().unwrap();
        let sizey: i32 = iter.next().unwrap().parse().unwrap();
        iter.next(); // Skip "255"

        image.width = sizex;
        image.height = sizey;

        let data_begin = header.len() - sizex as usize * sizey as usize;
        let data = &buffer[data_begin..];

        image.data = Some(data.to_vec());
    }

    fn load_image_raw(filename: &str, image: &mut Image, width: i32, height: i32) {
        let mut file = match File::open(filename) {
            Ok(file) => file,
            Err(_) => {
                eprintln!("Error opening {}!", filename);
                return;
            }
        };

        let metadata = file.metadata().unwrap();
        let filesize = metadata.len() as usize;
        let mut buffer = vec![0u8; filesize];

        file.read_exact(&mut buffer).unwrap();

        let mut final_width = width;
        let mut final_height = height;

        if final_width == 0 || final_height == 0 {
            final_width = (filesize as f64).sqrt() as i32;
            final_height = final_width;
            if (final_height * final_width) as usize != filesize {
                eprintln!("Error loading image {}, wrong file format!", filename);
                return;
            }
        }

        image.width = final_width;
        image.height = final_height;
        image.data = Some(buffer);
    }

    pub fn save_image(filename: &str, image: &Image) {
        let img_type = Self::get_image_type(filename);
        if img_type == IMGTYPE_UNSUPPORTED {
            eprintln!("Error saving image to {}, unknown image format!", filename);
            return;
        }
        Self::save_image_with_type(filename, image, img_type);
    }

    fn save_image_with_type(filename: &str, image: &Image, image_type: i32) {
        match image_type {
            IMGTYPE_BMP => Self::save_image_bmp(filename, image),
            IMGTYPE_PPM => Self::save_image_ppm(filename, image),
            IMGTYPE_PGM => Self::save_image_pgm(filename, image),
            IMGTYPE_RAW => Self::save_image_raw(filename, image),
            _ => {}
        }
    }

    fn save_image_bmp(filename: &str, image: &Image) {
        let mut file = match File::create(filename) {
            Ok(file) => file,
            Err(_) => {
                eprintln!("Error opening {}!", filename);
                return;
            }
        };

        let header = &[b'B', b'M'];
        file.write_all(header).unwrap();

        let row_size = (image.width as usize * 3 + 3) & !3;
        let pixel_data_offset = 54;
        let file_size = pixel_data_offset + row_size * image.height as usize;
        file.write_all(&(file_size as u32).to_le_bytes()).unwrap();

        file.write_all(&[0, 0, 0, 0]).unwrap(); // Reserved
        file.write_all(&(pixel_data_offset as u32).to_le_bytes()).unwrap();

        let info_header_size = 40u32;
        file.write_all(&info_header_size.to_le_bytes()).unwrap();
        file.write_all(&(image.width as u32).to_le_bytes()).unwrap();
        file.write_all(&(image.height as u32).to_le_bytes()).unwrap();
        file.write_all(&1u16.to_le_bytes()).unwrap(); // Planes
        file.write_all(&24u16.to_le_bytes()).unwrap(); // Bits per pixel
        file.write_all(&[0; 24]).unwrap(); // Remaining Info Header

        let mut row = vec![0u8; row_size];
        let data = &image.data.as_ref().unwrap();

        for y in 0..image.height {
            let offset = (image.height - 1 - y) as usize * image.width as usize * 3;
            row[..image.width as usize * 3].copy_from_slice(&data[offset..offset + image.width as usize * 3]);
            file.write_all(&row).unwrap();
        }
    }

    fn save_image_ppm(filename: &str, image: &Image) {
        let mut file = match File::create(filename) {
            Ok(file) => file,
            Err(_) => {
                eprintln!("Error opening {}!", filename);
                return;
            }
        };

        writeln!(file, "P6\n{} {}\n255", image.width, image.height).unwrap();

        if let Some(data) = &image.data {
            file.write_all(data).unwrap();
        }
    }

    fn save_image_pgm(filename: &str, image: &Image) {
        let mut file = match File::create(filename) {
            Ok(file) => file,
            Err(_) => {
                eprintln!("Error opening {}!", filename);
                return;
            }
        };

        writeln!(file, "P5\n{} {}\n255", image.width, image.height).unwrap();

        if let Some(data) = &image.data {
            for y in 0..image.height {
                for x in 0..image.width {
                    let idx = ((y * image.width + x) * 3) as usize;
                    let gray = data[idx];
                    file.write_all(&[gray]).unwrap();
                }
            }
        }
    }

    fn save_image_raw(filename: &str, image: &Image) {
        let mut file = match File::create(filename) {
            Ok(file) => file,
            Err(_) => {
                eprintln!("Error opening {}!", filename);
                return;
            }
        };

        if let Some(data) = &image.data {
            for byte in data.iter().step_by(3) {
                file.write_all(&[*byte]).unwrap();
            }
        }
    }
